begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email) select ('ab000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','template-'||n||'@example.invalid' from generate_series(1,4) n;
insert into public.staff_users(user_id,role) values('ab000000-0000-4000-8000-000000000001','admin'),('ab000000-0000-4000-8000-000000000002','office'),('ab000000-0000-4000-8000-000000000003','technician');
insert into public.catalog_items(id,code,name,category,unit,cost_cents,sale_cents,vat_basis_points,created_by,created_payload) values('cb000000-0000-4000-8000-000000000001','TEST-TPL','Miedź','material','meter',1200,2000,2300,'ab000000-0000-4000-8000-000000000001','{}');
create function pg_temp.fields(archived boolean default false,name text default 'Split standard') returns jsonb language sql as $$select jsonb_build_object('name',name,'description','Montaż do 5 m','workType','split','archived',archived,'lines',jsonb_build_array(jsonb_build_object('id','db000000-0000-4000-8000-000000000001','catalogId','cb000000-0000-4000-8000-000000000001','quantityMills',5000)))$$;
create function pg_temp.save(version integer,fields jsonb default pg_temp.fields()) returns jsonb language sql as $$select public.save_installation_template('eb000000-0000-4000-8000-000000000001',version,fields)$$;
create function pg_temp.detail() returns jsonb language sql as $$select public.installation_template_detail('eb000000-0000-4000-8000-000000000001')$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab000000-0000-4000-8000-000000000002',true);
select is(pg_temp.save(null)->>'version','0','Legacy fixed template still accepted');
select is(pg_temp.detail()->'template'->'fields'->'lines'->0->>'quantitySource',null,'Legacy source remains implicit fixed');
select is(pg_temp.save(0,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"area"'))->>'version','1','Area rule stored');
select is(pg_temp.detail()->'template'->'fields'->'lines'->0->>'quantitySource','area','Rule returned to clients');
select is(pg_temp.detail()->'lines'->0->>'quantityMills','5000','Catalog resolution returns coefficient, no hidden calculation');
select is(pg_temp.save(0,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"area"'))->>'version','1','Same rule retry is idempotent');
select throws_ok($$select pg_temp.save(0,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"length"'))$$,'40001',null,'Stale rule change denied');
select throws_ok($$select pg_temp.save(1,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"area*2"'))$$,'22023',null,'Expressions rejected');
select throws_ok($$select pg_temp.save(1,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','null'))$$,'22023',null,'Null source rejected');
select throws_ok($$select pg_temp.save(1,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','123'))$$,'22023',null,'Numeric source rejected');
select throws_ok($$select pg_temp.save(1,jsonb_set(pg_temp.fields(),'{lines,0,formula}','"area"'))$$,'22023',null,'Unknown formula fields rejected');
select throws_ok($$select pg_temp.save(1,jsonb_set(pg_temp.fields(),'{lines,0,quantityMills}','0'))$$,'22023',null,'Zero coefficient denied');
select is(pg_temp.save(1,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"length"'))->>'version','2','Length rule accepted');
select is(pg_temp.save(2,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"labor"'))->>'version','3','Labor rule accepted');
select is(pg_temp.save(3,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"travel"'))->>'version','4','Travel rule accepted');
select is(pg_temp.save(4,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"fixed"'))->>'version','5','Explicit fixed rule accepted');
reset role;
insert into public.customers(id,name) values('cc170000-0000-4000-8000-000000000001','Klient testu powierzchni');
create function pg_temp.offer(technical jsonb) returns jsonb language sql as $$select jsonb_build_object('customerId','cc170000-0000-4000-8000-000000000001','locationId',null,'title','Podłogówka','workType','underfloor','technical',technical,'archived',false,'mainVariantId','dd170000-0000-4000-8000-000000000001','variants',jsonb_build_array(jsonb_build_object('id','dd170000-0000-4000-8000-000000000001','name','Główna','lines','[]'::jsonb,'internalNote','','customerNote','','targetMarginBasisPoints',3000,'overrideNetCents',null)))$$;
set local role authenticated;
select is(public.save_offer('ee170000-0000-4000-8000-000000000001',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0,"areaMills":40000}'),null)->'technical'->>'areaMills','40000','Offer stores surface measurement');
select is(public.save_offer('ee170000-0000-4000-8000-000000000002',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0}'),null)->>'version','0','Old offers without area still accepted');
select throws_ok($$select public.save_offer('ee170000-0000-4000-8000-000000000003',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0,"areaMills":-1}'),null)$$,'22023',null,'Negative area rejected');
select throws_ok($$select public.save_offer('ee170000-0000-4000-8000-000000000003',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0,"areaMills":0.1}'),null)$$,'22023',null,'Fractional mills rejected');
select throws_ok($$select public.save_offer('ee170000-0000-4000-8000-000000000003',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0,"areaMills":10000001}'),null)$$,'22023',null,'Area limit enforced');
select throws_ok($$select public.save_offer('ee170000-0000-4000-8000-000000000003',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0,"areaMills":null}'),null)$$,'22023',null,'Null area rejected');
select throws_ok($$select public.save_offer('ee170000-0000-4000-8000-000000000003',pg_temp.offer('{"lengthMills":0,"laborMills":0,"travelMills":0,"extra":1}'),null)$$,'22023',null,'Unknown measurements rejected');
select set_config('request.jwt.claim.sub','ab000000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.save(5,jsonb_set(pg_temp.fields(),'{lines,0,quantitySource}','"area"'))$$,'42501',null,'Technician cannot change rules');
select throws_ok($$select pg_temp.detail()$$,'42501',null,'Technician cannot read coefficients and prices');
reset role;
set local role anon;
select throws_ok($$select public.save_installation_template('eb000000-0000-4000-8000-000000000001',5,'{}')$$,'42501',null,'Anonymous cannot change rules');
select * from finish();
rollback;
